from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits

import traceback

# --- Constants ---
TARGET_PERSON_NAME = "Sofia Coppola"
TARGET_JOB_ROLE = "Director"

def get_person_id(person_name):
    """
    Searches for a person by name and extracts their unique ID.
    """
    try:
        response = Search_person(query=person_name)
        results = response.get("results", [])

        if not results:
            print(f"No person found with name: {person_name}")
            return None

        # Use the first result as the primary match
        person = results[0]
        return person.get("id")
    except Exception as e:
        print(f"Error while searching for person {person_name}: {e}")
        return None

def get_directed_movies_count(person_id):
    """
    Retrieves movie credits for a person and counts how many they directed.
    """
    try:
        credits = Get_person_movie_credits(person_id=person_id)
        crew = credits.get("crew", [])

        # Filter crew members where the 'job' field matches the Director role
        # Using case-insensitive comparison for normalization
        directed_movies = [
            movie for movie in crew 
            if movie.get("job", "").strip().lower() == TARGET_JOB_ROLE.lower()
        ]

        return len(directed_movies)
    except Exception as e:
        print(f"Error while retrieving movie credits for ID {person_id}: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the number of movies directed by the target person.
    """
    person_id = get_person_id(TARGET_PERSON_NAME)

    if person_id is None:
        print(f"Could not find ID for {TARGET_PERSON_NAME}. Task failed.")
        return

    movie_count = get_directed_movies_count(person_id)

    if movie_count is not None:
        print(f"The number of movies directed by {TARGET_PERSON_NAME} is: {movie_count}")
    else:
        print(f"Could not determine the number of movies directed by {TARGET_PERSON_NAME}.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

