from Get_trending_movies import Get_trending_movies
from Get_movie_credits import Get_movie_credits

import traceback

# --- Constants ---
TIME_WINDOW = "day"
DIRECTOR_JOB_TITLE = "Director"

def get_top_trending_movie_id():
    """
    Fetches the trending movies for the specified time window and returns the ID of the most trending one.
    """
    try:
        data = Get_trending_movies(time_window=TIME_WINDOW)
        results = data.get("results", [])
        if not results:
            return None

        # The API typically returns results sorted by popularity; the first item is the most trending.
        top_movie = results[0]
        return top_movie.get("id")
    except Exception as e:
        print(f"Error fetching trending movies: {e}")
        return None

def get_director_name(movie_id):
    """
    Fetches movie credits and extracts the name of the person with the job 'Director'.
    """
    try:
        credits_data = Get_movie_credits(movie_id=movie_id)
        crew = credits_data.get("crew", [])

        # Search for the crew member whose 'job' is 'Director'
        for member in crew:
            if member.get("job") == DIRECTOR_JOB_TITLE:
                return member.get("name")

        return "Director not found in credits."
    except Exception as e:
        print(f"Error fetching movie credits: {e}")
        return None

def main():
    """
    Orchestrates the process of finding the director of today's most trending movie.
    """
    movie_id = get_top_trending_movie_id()
    if movie_id is None:
        print("Could not retrieve trending movies.")
        return

    director_name = get_director_name(movie_id)
    if director_name:
        print(f"The director of today's most trending movie is: {director_name}")
    else:
        print("Could not determine the director.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

