from Search_movie import Search_movie
from Get_movie_credits import Get_movie_credits

import traceback

# --- Constants ---
TARGET_MOVIE_TITLE = "Twilight"
DIRECTOR_JOB_TITLE = "Director"

def find_movie_id():
    """
    Searches for the movie by title and extracts the movie ID.
    """
    try:
        # Rule 3 & 10: Use Search_movie with query parameter. 
        # response_schema: results is an array of objects containing 'id' and 'title'.
        search_results = Search_movie(query=TARGET_MOVIE_TITLE)
        results = search_results.get("results", [])

        if not results:
            print(f"No movies found matching '{TARGET_MOVIE_TITLE}'.")
            return None

        # Rule 14: Lenient comparison for the title
        for movie in results:
            if TARGET_MOVIE_TITLE.lower() in movie.get("title", "").lower():
                return movie.get("id")

        # Fallback to first result if no exact/partial match found but results exist
        return results[0].get("id")

    except Exception as e:
        print(f"Error while searching for movie ID: {e}")
        return None

def get_director_name(movie_id):
    """
    Retrieves credits for the movie ID and filters for the person with the job 'Director'.
    """
    if movie_id is None:
        return None

    try:
        # Rule 3 & 10: Use Get_movie_credits with movie_id.
        # response_schema: returns object with 'crew' array.
        credits_data = Get_movie_credits(movie_id=movie_id)
        crew = credits_data.get("crew", [])

        # Rule 10 & 14: Filter crew where 'job' is 'Director'
        for member in crew:
            if member.get("job", "").lower() == DIRECTOR_JOB_TITLE.lower():
                return member.get("name")

        return "Director not found in credits."

    except Exception as e:
        print(f"Error while retrieving director from credits: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the director of the target movie.
    """
    movie_id = find_movie_id()
    if movie_id:
        director = get_director_name(movie_id)
        if director:
            print(f"The director of the movie '{TARGET_MOVIE_TITLE}' is: {director}")
        else:
            print(f"Could not determine the director for '{TARGET_MOVIE_TITLE}'.")
    else:
        print(f"Could not find a movie ID for '{TARGET_MOVIE_TITLE}'.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        # Rule 9: Top-level exception handler printing full traceback to stderr
        traceback.print_exc(file=sys.stderr)

