from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_release_dates import Get_movie_release_dates

import traceback

# --- Constants ---
TARGET_PERSON_NAME = "Clint Eastwood"

def get_person_id_by_name(name):
    """
    Searches for a person by name and returns their unique ID.
    """
    try:
        response = Search_person(query=name)
        results = response.get("results", [])
        if not results:
            print(f"No results found for person: {name}")
            return None

        # Find the best match (lenient comparison)
        for person in results:
            if name.lower() in person.get("name", "").lower():
                return person.get("id")

        # Fallback to first result if no strict match but results exist
        return results[0].get("id")
    except Exception as e:
        print(f"Error searching for person {name}: {e}")
        return None

def get_latest_movie_id(person_id):
    """
    Retrieves movie credits for a person and identifies the movie with the latest release date.
    """
    try:
        credits = Get_person_movie_credits(person_id=person_id)
        # Combine cast and crew to find all movies the person was involved in
        all_movies = credits.get("cast", []) + credits.get("crew", [])

        if not all_movies:
            print("No movie credits found for the person.")
            return None

        # Filter movies that have a release_date and sort them descending
        movies_with_dates = [m for m in all_movies if m.get("release_date")]
        if not movies_with_dates:
            print("No movies with release dates found.")
            return None

        # Sort by release_date string (YYYY-MM-DD allows lexicographical sort)
        latest_movie = max(movies_with_dates, key=lambda x: x.get("release_date"))
        return latest_movie.get("id")
    except Exception as e:
        print(f"Error retrieving latest movie for person ID {person_id}: {e}")
        return None

def get_movie_release_date(movie_id):
    """
    Fetches the release dates for a specific movie and returns the most relevant date.
    """
    try:
        response = Get_movie_release_dates(movie_id=movie_id)
        results = response.get("results", [])

        if not results:
            print(f"No release date records found for movie ID {movie_id}.")
            return None

        # Collect all release dates across all countries
        all_dates = []
        for country_entry in results:
            dates_list = country_entry.get("release_dates", [])
            for date_obj in dates_list:
                date_val = date_obj.get("release_date")
                if date_val:
                    all_dates.append(date_val)

        if not all_dates:
            return None

        # Return the latest date found in the release dates list
        return max(all_dates)
    except Exception as e:
        print(f"Error retrieving release date for movie ID {movie_id}: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the release date of Clint Eastwood's latest movie.
    """
    try:
        # 1. Find Person ID
        person_id = get_person_id_by_name(TARGET_PERSON_NAME)
        if person_id is None:
            return

        # 2. Find Latest Movie ID
        movie_id = get_latest_movie_id(person_id)
        if movie_id is None:
            return

        # 3. Get Release Date
        release_date = get_movie_release_date(movie_id)

        if release_date:
            print(f"The latest movie for {TARGET_PERSON_NAME} is scheduled to be released on: {release_date}")
        else:
            print(f"Could not find a release date for the latest movie of {TARGET_PERSON_NAME}.")

    except Exception:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

