    try:
        response = Search_company(query=company_name)
        results = response.get("results", [])

        if not results:
            print(f"No companies found matching '{company_name}'.")
            return None

        # Use lenient comparison to find the best match
        for company in results:
            if company_name.lower() in company.get("name", "").lower():
                return company.get("id")

        # Fallback to the first result if no strict substring match
        return results[0].get("id")
    except Exception as e:
