from Search_collections import Search_collections
from Get_collection_details import Get_collection_details
from Get_movie_release_dates import Get_movie_release_dates

import traceback

# --- API calling code ---
import os
import requests

def Search_collections(query):
    if query is None:
        raise ValueError("`query` is required.")
    url = "https://api.themoviedb.org/3/search/collection"
    bearer_token = os.getenv("TMDB_BEARER_TOKEN")
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {bearer_token}"
    }
    params = {"query": query}
    response = requests.get(url, headers=headers, params=params)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def Get_collection_details(collection_id):
    if collection_id is None:
        raise ValueError("`collection_id` is required.")
    url = f"https://api.themoviedb.org/3/collection/{collection_id}"
    bearer_token = os.getenv("TMDB_BEARER_TOKEN")
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {bearer_token}"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def Get_movie_release_dates(movie_id):
    if movie_id is None:
        raise ValueError("`movie_id` is required.")
    url = f"https://api.themoviedb.org/3/movie/{movie_id}/release_dates"
    bearer_token = os.getenv("TMDB_BEARER_TOKEN")
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {bearer_token}"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def find_collection_id(query):
    """
    Searches for a collection by name and returns the ID of the first result.
    """
    response = Search_collections(query=query)
    results = response.get("results", [])
    if not results:
        raise Exception(f"No collections found for query: {query}")

    return results[0].get("id")

def get_movies_in_collection(collection_id):
    """
    Retrieves the list of movies (parts) belonging to a specific collection.
    """
    details = Get_collection_details(collection_id=collection_id)
    return details.get("parts", [])

def fetch_movie_release_dates(movies):
    """
    Iterates through a list of movie objects and fetches their release dates.
    """
    movie_dates_info = []
    for movie in movies:
        movie_id = movie.get("id")
        movie_name = movie.get("name")
        if movie_id is None:
            continue

        dates_data = Get_movie_release_dates(movie_id=movie_id)
        movie_dates_info.append({
            "name": movie_name,
            "release_data": dates_data.get("results", [])
        })

    return movie_dates_info

def orchestrate_release_date_lookup():
    """
    Main logic flow to find release dates for movies in a specific collection.
    """
    # C2: Task parameters hardcoded as named constants
    COLLECTION_QUERY = "The Hobbit"

    # 1. Find the collection ID
    collection_id = find_collection_id(COLLECTION_QUERY)
    if collection_id is None:
        raise Exception("Collection ID not found.")

    # 2. Get movies in that collection
    movies = get_movies_in_collection(collection_id)
    if not movies:
        raise Exception(f"No movies found in the collection '{COLLECTION_QUERY}'.")

    # 3. Fetch release dates for each movie
    all_dates = fetch_movie_release_dates(movies)

    # 4. Format and print the output
    print(f"Release dates for movies in the collection '{COLLECTION_QUERY}':")
    print("-" * 50)
    for item in all_dates:
        name = item["name"]
        results = item["release_data"]

        if not results:
            print(f"Movie: {name} - No release date data available.")
            continue

        print(f"Movie: {name}")
        for country_entry in results:
            country_code = country_entry.get("iso_3166_1")
            dates_list = country_entry.get("release_dates", [])
            for rd in dates_list:
                date = rd.get("release_date")
                if date:
                    print(f"  - {country_code}: {date}")
        print("-" * 20)

if __name__ == "__main__":
    try:
        orchestrate_release_date_lookup()
    except Exception:
        traceback.print_exc(file=sys.stderr)

