from Search_collections import Search_collections
from Get_collection_details import Get_collection_details
from Get_movie_details import Get_movie_details

import traceback

# --- Constants ---
COLLECTION_QUERY = "Lord of the Rings"

def find_collection_id(query):
    """
    Searches for a collection by name and returns the ID of the first result.
    """
    try:
        response = Search_collections(query=query)
        results = response.get("results", [])
        if not results:
            print(f"No collections found for query: {query}")
            return None

        # Return the 'id' of the first result as per response_schema
        return results[0].get("id")
    except Exception as e:
        print(f"Error finding collection ID: {e}")
        return None

def get_collection_movies(collection_id):
    """
    Retrieves the list of movies (parts) belonging to a specific collection.
    """
    try:
        details = Get_collection_details(collection_id=collection_id)
        # 'parts' contains the list of movies in the collection
        return details.get("parts", [])
    except Exception as e:
        print(f"Error retrieving collection movies: {e}")
        return None

def get_first_movie_release_date(movie_list):
    """
    Identifies the first movie in the list and retrieves its release date.
    """
    if not movie_list:
        print("The movie list is empty.")
        return None

    try:
        # The first movie in the 'parts' array
        first_movie = movie_list[0]
        movie_id = first_movie.get("id")

        if movie_id is None:
            return None

        movie_details = Get_movie_details(movie_id=movie_id)
        # Extract 'release_date' from movie details schema
        return movie_details.get("release_date")
    except Exception as e:
        print(f"Error retrieving first movie release date: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the release date of the first movie in the LOTR collection.
    """
    # 1. Find the collection ID
    collection_id = find_collection_id(COLLECTION_QUERY)
    if collection_id is None:
        return

    # 2. Get the list of movies in that collection
    movies = get_collection_movies(collection_id)
    if movies is None:
        return

    # 3. Get the release date of the first movie
    release_date = get_first_movie_release_date(movies)

    if release_date:
        print(f"The first movie of the collection '{COLLECTION_QUERY}' was released on: {release_date}")
    else:
        print(f"Could not determine the release date for the first movie of '{COLLECTION_QUERY}'.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

