import traceback

# --- Constants ---
TARGET_SHOW_NAME = "Game of Thrones"

def find_tv_show_id(show_name):
    """
    Searches for a TV show by name and returns the ID of the first result.
    """
    try:
        search_results = Search_tv(query=show_name)
        results = search_results.get("results", [])

        if not results:
            print(f"No TV shows found matching '{show_name}'.")
            return None

        # Return the ID of the first result as the most likely match
        return results[0].get("id")
    except Exception as e:
        print(f"Error while searching for TV show: {e}")
        return None

def get_producing_network_id(series_id):
    """
    Retrieves the details of a TV show and extracts the ID of the first producing network.
    """
    try:
        show_details = Get_tv_details(series_id=series_id)
        networks = show_details.get("networks", [])
        if not networks:
            print("No producing networks found for this show.")
            return None

        # Extract the 'id' from the first network in the list
        return networks[0].get("id")
    except Exception as e:
        print(f"Error while retrieving TV show details: {e}")
        return None

def get_network_homepage(network_id):
    """
    Retrieves the details of a network and returns its homepage URL.
    """
    try:
        network_details = Get_network_details(network_id=network_id)
        return network_details.get("homepage")
    except Exception as e:
        print(f"Error while retrieving network details: {e}")
        return None

