    show_id = find_tv_show_id(TARGET_SHOW_NAME)
    if show_id is None:
        return

    # 2. Find the network ID associated with that show
    network_id = get_producing_network_id(show_id)
    if network_id is None:
        return

    # 3. Get the homepage of that network
