import traceback

# --- API calling code ---
import os
import requests

def Search_movie(query):
    if query is None:
        raise ValueError("`query` is required.")
    url = "https://api.themoviedb.org/3/search/movie"
    bearer_token = os.getenv("TMDB_BEARER_TOKEN")
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {bearer_token}"
    }
    params = {"query": query}
    response = requests.get(url, headers=headers, params=params)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def Get_movie_details(movie_id):
    if movie_id is None:
        raise ValueError("`movie_id` is required.")
    url = f"https://api.themoviedb.org/3/movie/{movie_id}"
    bearer_token = os.getenv("TMDB_BEARER_TOKEN")
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {bearer_token}"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def Get_company_details(company_id):
    if company_id is None:
        raise ValueError("`company_id` is required.")
    url = f"https://api.themoviedb.org/3/company/{company_id}"
    bearer_token = os.getenv("TMDB_BEARER_TOKEN")
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {bearer_token}"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

# --- Logic ---

def get_movie_id_by_title(title):
    """
    Searches for a movie by title and returns the ID of the first result.
    """
    response = Search_movie(query=title)
    results = response.get("results", [])
    if not results:
        raise Exception(f"No movies found for title: {title}")
    return results[0].get("id")

def get_production_company_id(movie_id):
    """
    Retrieves the ID of the first production company associated with the movie.
    """
    details = Get_movie_details(movie_id=movie_id)
    companies = details.get("production_companies", [])
    if not companies:
        raise Exception(f"No production companies found for movie ID: {movie_id}")
    return companies[0].get("id")

def get_company_headquarters(company_id):
    """
    Retrieves the headquarters location of a company by its ID.
    """
    company_info = Get_company_details(company_id=company_id)
    headquarters = company_info.get("headquarters")
    if not headquarters:
        raise Exception(f"Headquarters not found for company ID: {company_id}")
    return headquarters

def main():
    # C2: Task parameters hardcoded as named constants
    TARGET_MOVIE_TITLE = "The Shawshank Redemption"

    # 1. Find Movie ID
    movie_id = get_movie_id_by_title(TARGET_MOVIE_TITLE)

    # 2. Find Company ID
    company_id = get_production_company_id(movie_id)

    # 3. Find Headquarters
    location = get_company_headquarters(company_id)

    print(f"The headquarter of the company that created '{TARGET_MOVIE_TITLE}' is: {location}")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_movie_credits import Get_movie_credits
from Get_person_tv_credits import Get_person_tv_credits

import traceback

# --- Constants ---
TARGET_MOVIE_TITLE = "Mulholland Drive"
DIRECTOR_JOB_TITLE = "Director"

def find_movie_id(movie_title):
    """
    Searches for a movie by title and returns its ID.
    """
    try:
        response = Search_movie(query=movie_title)
        results = response.get("results", [])
        if not results:
            print(f"No movies found for title: {movie_title}")
            return None

        # Return the ID of the first result
        return results[0].get("id")
    except Exception as e:
        print(f"Error finding movie ID: {e}")
        return None

def get_director_id(movie_id):
    """
    Retrieves the credits for a movie and extracts the ID of the person with the job 'Director'.
    """
    try:
        credits_data = Get_movie_credits(movie_id=movie_id)
        crew = credits_data.get("crew", [])

        for member in crew:
            # Use lenient comparison for the job title
            if member.get("job", "").lower() == DIRECTOR_JOB_TITLE.lower():
                return member.get("id")

        print("No director found in the movie credits.")
        return None
    except Exception as e:
        print(f"Error getting director ID: {e}")
        return None

def get_director_tv_series(person_id):
    """
    Retrieves TV credits for a person and returns a list of TV series names they directed.
    """
    try:
        tv_credits_data = Get_person_tv_credits(person_id=person_id)
        crew_credits = tv_credits_data.get("crew", [])

        tv_series_names = []
        for credit in crew_credits:
            # Filter for directing roles in TV series
            if credit.get("job", "").lower() == DIRECTOR_JOB_TITLE.lower():
                name = credit.get("name")
                if name:
                    tv_series_names.append(name)

        return tv_series_names
    except Exception as e:
        print(f"Error getting director's TV series: {e}")
        return []

def main():
    """
    Orchestrates the flow to find TV series directed by the director of a specific movie.
    """
    # 1. Find the movie ID
    movie_id = find_movie_id(TARGET_MOVIE_TITLE)
    if movie_id is None:
        return

    # 2. Find the director's person ID
    director_id = get_director_id(movie_id)
    if director_id is None:
        return

    # 3. Find TV series directed by that person
    tv_series = get_director_tv_series(director_id)

    if tv_series:
        print(f"TV series directed by the director of {TARGET_MOVIE_TITLE}:")
        for series in tv_series:
            print(f"- {series}")
    else:
        print(f"No TV series found that were directed by the director of {TARGET_MOVIE_TITLE}.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_tv import Search_tv
from Get_tv_details import Get_tv_details

import traceback

# --- Constants ---
TARGET_SHOW_NAME = "Sword Art Online"

def find_tv_show_id():
    """
    Searches for the TV show by name and extracts the ID.
    """
    try:
        # Rule 3 & 10: Use Search_tv with query parameter. 
        # response_schema: results is an array of objects containing 'id' and 'name'.
        response = Search_tv(query=TARGET_SHOW_NAME)

        results = response.get("results", [])
        if not results:
            print(f"No results found for {TARGET_SHOW_NAME}.")
            return None

        # Rule 14: Lenient comparison for the show name
        for show in results:
            if TARGET_SHOW_NAME.lower() in show.get("name", "").lower():
                return show.get("id")

        # Fallback to first result if no strict match but results exist
        return results[0].get("id")

    except Exception as e:
        print(f"Error while searching for TV show: {e}")
        return None

def get_season_count(series_id):
    """
    Retrieves the number of seasons for a given series ID.
    """
    if series_id is None:
        return None

    try:
        # Rule 3 & 10: Use Get_tv_details with series_id.
        # response_schema: contains 'number_of_seasons' as an integer.
        details = Get_tv_details(series_id=series_id)
        return details.get("number_of_seasons")
    except Exception as e:
        print(f"Error while fetching TV details: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the number of seasons for the target show.
    """
    show_id = find_tv_show_id()
    if show_id is None:
        print(f"Could not find the ID for {TARGET_SHOW_NAME}.")
        return

    season_count = get_season_count(show_id)
    if season_count is not None:
        print(f"There are {season_count} seasons of {TARGET_SHOW_NAME}.")
    else:
        print(f"Could not retrieve the season count for {TARGET_SHOW_NAME}.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        # Rule 9: Top-level exception handler printing full traceback to stderr
        traceback.print_exc(file=sys.stderr)
